package tn.esprit.partnerintelligence.controller;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import tn.esprit.partnerintelligence.dto.RecommendationDecisionRequest;import tn.esprit.partnerintelligence.entity.RecommendationDecision;import tn.esprit.partnerintelligence.service.DecisionWorkflowService;@RestController @RequestMapping("/api/partner-intelligence/v1/recommendations") public class RecommendationDecisionController{ private final DecisionWorkflowService s; public RecommendationDecisionController(DecisionWorkflowService s){this.s=s;} @PostMapping("/{recommendationId}/decision") public RecommendationDecision decide(@PathVariable Long recommendationId,@Valid @RequestBody RecommendationDecisionRequest req){ return s.decide(recommendationId,req);} }